    def __init__(self, name, datas):
        self._name = name
        self._datas = datas

    def get_data_by_name(self, name):
        """Get a data item by its name - fixed implementation."""
        for data in self._datas:
            if data.name == name:  # Fixed: use data.name instead of data.get('name')
